CREATE TEMP TABLE catalogue_input ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"id":"e5923ac1-27b3-5c36-8bc0-539211a8bafd","source_id":"0358","name_en":"dumbbell one arm reverse wrist curl","name_ar":"\u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0630\u0631\u0627\u0639 \u0648\u0627\u062d\u062f\u0629 \u0644\u0644\u0645\u0639\u0635\u0645 \u0627\u0644\u0639\u0643\u0633\u064a","match_names":["dumbbell one arm reverse wrist curl"],"muscle":"forearms","equipment":"dumbbell","aliases":["dumbbell one arm reverse wrist curl"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Sit on a bench or chair with your feet flat on the ground.\nHold a dumbbell in one hand with an overhand grip, palm facing down.\nRest your forearm on your thigh, with your wrist hanging off the edge.\nSlowly lower the dumbbell towards the ground by flexing your wrist.\nPause for a moment at the bottom, then slowly curl your wrist back up towards your body.\nRepeat for the desired number of repetitions, then switch to the other arm.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0623\u0648 \u0643\u0631\u0633\u064a \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u064a\u062f \u0648\u0627\u062d\u062f\u0629 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u0629 \u0627\u0644\u064a\u062f \u0644\u0644\u0623\u0633\u0641\u0644.\n\u0636\u0639 \u0633\u0627\u0639\u062f\u0643 \u0639\u0644\u0649 \u0641\u062e\u0630\u0643\u060c \u0645\u0639 \u062a\u0639\u0644\u064a\u0642 \u0645\u0639\u0635\u0645\u0643 \u0645\u0646 \u0627\u0644\u062d\u0627\u0641\u0629.\n\u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628\u0637\u0621 \u0646\u062d\u0648 \u0627\u0644\u0623\u063