u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0633\u0641\u0644.\n\u0636\u0639 \u0633\u0627\u0639\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f\u060c \u0645\u0639 \u0627\u0644\u0633\u0645\u0627\u062d \u0644\u0645\u0639\u0635\u0645\u064a\u0643 \u0628\u0627\u0644\u062a\u062f\u0644\u064a \u0645\u0646 \u0627\u0644\u062d\u0627\u0641\u0629.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0645\u0639\u0635\u0645\u064a\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0628\u0628\u0637\u0621\u060c \u0628\u062d\u064a\u062b \u064a\u0643\u0648\u0646 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0646\u062d\u0648 \u062c\u0633\u0645\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0368","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"forearms","secondary_muscles":["biceps","brachialis"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0368-3tAXPQ6.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0368-3tAXPQ6.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"f7adab7a-f975-5332-80a5-1a0ef705f847","source_id":"0369","name_en":"dumbbell over bench wrist curl","name_ar":"\u0627\u0644\u062f\u0645\u0628\u0644 \u0639\u0644\u0649 \u062d\u0644\u064a\u0642\u0629 \u0627\u0644\u0645\u0639\u0635\u0645 \u0645\u0642\u0627\u0639\u062f \u0627\u0644\u0628\u062f\u0644\u0627\u0621","match_names":["dumbbell over bench wrist curl"],"muscle":"forearms","equipment":"dumbbell","aliases":["dumbbell over bench wrist curl"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Sit on a bench with your forearms resting on the bench and your palms facing up, holding a dumbbell in each hand.\nAllow your wrists to hang over the edge of the bench.\nSlowly curl your wrists upward, squeezing your forearms at the top of the movement.\nPause for a moment, then slowly lower your wrists back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0639 \u0648\u0636\u0639 \u0633\u0627\u0639\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0648\u0631\u0627\u062d\u062a\u064a \u064a\u062f\u064a\u0643 \u0645\u062a\u062c\u0647\u062a\u064a\u0646 \u0644\u0644\u0623\u0639\u0644\u0649\u060c \u0645\u0645\u0633\u0643\u064b\u0627 \u0628\u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f.\n\u0627\u0633\u0645\u062d \u0644\u0645\u0639\u0635\u0645\u064a\u0643 \u0628\u0627\u0644\u062a\u0639\u0644\u064a\u0642 \u0639\u0644\u0649 \u062d\u0627\u0641\u0629 \u0627\u0644\u0645\u0642\u0639\u062f.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0645\u0639\u0635\u0645\u064a\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0628\u0628\u0637\u0621\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0633\u0627\u0639\u062f\u064a\u0643 \u0641\u064a \u0623\u0639\u0644\u0649 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0645\u0639\u0635\u0645\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0369","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"forearms","secondary_muscles":["biceps","brachialis"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0369-D1xYJAU.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0369-D1xYJAU.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"449b7339-15b8-5457-8a94-040a98d39edd","source_id":"1329","name_en":"dumbbell palm rotational bent over row","name_ar":"\u0631\u0627\u062d\u0629 \u0627\u0644\u064a\u062f \u0627\u0644\u062f\u0645\u0628\u0644 \u0639\u0627\u0632\u0645\u0629 \u0639\u0644\u0649 \u0627\u0644\u0635\u0641","match_names":["dumbbell palm rotational bent over row"],"muscle":"back","equipment":"dumbbell","aliases":["dumbbell palm rotational bent over row"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.\nBend forward at the hips, keeping your back straight and your knees slightly bent.\nLet your arms hang straight down, palms facing your body.\nEngage your core and pull the dumbbells up towards your chest, keeping your elbows close to your body.\nAs you pull the dumbbells up, rotate your palms so they face away from your body.\nSqueeze your shoulder blades together at the top of the movement.\nSlowly lower the dumbbells back down to the starting position, rotating your palms back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629.\n\u0627\u0646\u062d\u0646\u0649 \u0644\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u062f\u0639 \u0630\u0631\u0627\u0639\u064a\u0643 \u062a\u062a\u062f\u0644\u0649 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0625\u0644\u0649 \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u0648\u0631\u0627\u062d\u062a\u0627 \u0627\u0644\u064a\u062f \u062a\u0648\u0627\u062c\u0647\u0627\u0646 \u062c\u0633\u062f\u0643.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u0633\u062d\u0628 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0633\u0645\u0643.\n\u0623\u062b\u0646\u0627\u0621 \u0642\u064a\u0627\u0645\u0643 \u0628\u0633\u062d\u0628 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0644\u0623\u0639\u0644\u0649\u060c \u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u0631\u0627\u062d\u062a\u064a \u064a\u062f\u064a\u0643 \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0645\u062a\u062c\u0647\u0629 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u062c\u0633\u0645\u0643.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629\u060c \u0645\u0639 \u062a\u062f\u0648\u064a\u0631 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1329","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"upper back","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1329-wt6rwjk.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1329-wt6rwjk.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"c6212baa-7555-5e9a-8116-f3a5617be021","source_id":"1623","name_en":"dumbbell palms in incline bench press","name_ar":"\u0631\u0627\u062d\u0629 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0645\u0642\u0627\u0639\u062f \u0627\u0644\u0628\u062f\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u062d\u062f\u0631\u0629","match_names":["dumbbell palms in incline bench press"],"muscle":"triceps","equipment":"dumbbell","aliases":["dumbbell palms in incline bench press"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Set up an incline bench at a 45-degree angle.\nSit on the bench with your back against the backrest and feet flat on the ground.\nHold a dumbbell in each hand with an overhand grip, palms facing inwards.\nExtend your arms straight up above your chest, keeping a slight bend in your elbows.\nLower the dumbbells slowly towards your shoulders, keeping your elbows close to your body.\nPause for a moment at the bottom, then press the dumbbells back up to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u0625\u0639\u062f\u0627\u062f \u0645\u0642\u0639\u062f \u0645\u0627\u0626\u0644 \u0628\u0632\u0627\u0648\u064a\u0629 45 \u062f\u0631\u062c\u0629.\n\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0645\u0639 \u0648\u0636\u0639 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0645\u0633\u0646\u062f \u0627\u0644\u0638\u0647\u0631 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u062f\u0627\u062e\u0644.\n\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0641\u0648\u0642 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0646\u062d\u0646\u0627\u0621 \u0637\u0641\u064a\u0641 \u0641\u064a \u0645\u0631\u0641\u0642\u064a\u0643.\n\u0627\u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0628\u0628\u0637\u0621 \u0646\u062d\u0648 \u0643\u062a\u0641\u064a\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0633\u0645\u0643.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u062f\u0645\u0628\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1623","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["chest","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1623-8eqjhOl.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1623-8eqjhOl.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"32f0bb1f-c3d5-51ea-83f5-bc6a6714de57","source_id":"0370","name_en":"dumbbell peacher hammer curl","name_ar":"\u062d\u0644\u064a\u0642\u0629 \u0645\u0637\u0631\u0642\u0629 \u0627\u0644\u062f\u0645\u0628\u0644","match_names":["dumbbell peacher hammer curl"],"muscle":"biceps","equipment":"dumbbell","aliases":["dumbbell peacher hammer curl"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand up straight with a dumbbell in each hand, palms facing your torso.\nKeep your elbows close to your torso and rotate the palms of your hands until they are facing forward.\nThis will be your starting position.\nNow, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.\nContinue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.\nHold the contracted position for a brief pause as you squeeze your biceps.\nThen, inhale and slowly begin to lower the dumbbells back to the starting position.\nRepeat for the recommended amount of repetitions.","steps_ar":"\u0642\u0641 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0645\u0639 \u0648\u062c\u0648\u062f \u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0625\u0644\u0649 \u062c\u0630\u0639\u0643.\n\u0623\u0628\u0642\u0650 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0630\u0639\u0643 \u0648\u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u0631\u0627\u062d\u062a\u064a \u064a\u062f\u064a\u0643 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d\u0627 \u0645\u062a\u062c\u0647\u064a\u0646 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0633\u064a\u0643\u0648\u0646 \u0647\u0630\u0627 \u0647\u0648 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u062e\u0627\u0635 \u0628\u0643.\n\u0627\u0644\u0622\u0646\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u062b\u0628\u0627\u062a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u0630\u0631\u0627\u0639\u064a\u0646\u060c \u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0644\u0641 \u0627\u0644\u0623\u0648\u0632\u0627\u0646 \u0623\u062b\u0646\u0627\u0621 \u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0631\u0641\u0639 \u0627\u0644\u0623\u0648\u0632\u0627\u0646 \u062d\u062a\u0649 \u062a\u0646\u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646 \u0628\u0634\u0643\u0644 \u0643\u0627\u0645\u0644 \u0648\u064a\u0635\u0628\u062d \u0627\u0644\u062f\u0645\u0628\u0644 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641.\n\u0627\u062d\u062a\u0641\u0638 \u0628\u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0646\u0642\u0628\u0636\u0629 \u0644\u062a\u0648\u0642\u0641 \u0642\u0635\u064a\u0631 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u062b\u0645 \u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u0648\u0627\u0628\u062f\u0623 \u0628\u0628\u0637\u0621 \u0641\u064a \u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0644\u0644\u0643\u0645\u064a\u0629 \u0627\u0644\u0645\u0648\u0635\u0649 \u0628\u0647\u0627 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0370","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0370-F1KxjBa.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0370-F1KxjBa.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"c670bf89-f925-5c5d-8fcb-02f6e85f550b","source_id":"0371","name_en":"dumbbell plyo squat","name_ar":"\u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0627\u0644\u062f\u0645\u0628\u0644 plyo","match_names":["dumbbell plyo squat"],"muscle":"glutes","equipment":"dumbbell","aliases":["dumbbell plyo squat"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.\nLower your body into a squat position by bending your knees and pushing your hips back.\nAs you reach the bottom of the squat, explode upward, jumping off the ground.\nWhile in the air, quickly switch the position of your feet, landing with your opposite foot forward.\nImmediately lower your body back into a squat position and repeat the jump, switching your feet again.\nContinue alternating the position of your feet with each jump for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u062f\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641.\n\u0639\u0646\u062f\u0645\u0627 \u062a\u0635\u0644 \u0625\u0644\u0649 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0633\u0641\u0644\u064a \u0645\u0646 \u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621\u060c \u0627\u0646\u0641\u062c\u0631 \u0644\u0644\u0623\u0639\u0644\u0649\u060c \u0648\u0627\u0642\u0641\u0632 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u062b\u0646\u0627\u0621 \u0648\u062c\u0648\u062f\u0643 \u0641\u064a \u0627\u0644\u0647\u0648\u0627\u0621\u060c \u0642\u0645 \u0628\u062a\u0628\u062f\u064a\u0644 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0633\u0631\u0639\u0629\u060c \u0648\u0647\u0628\u0637 \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u0645\u0639\u0627\u0643\u0633\u0629 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0639\u0644\u0649 \u0627\u0644\u0641\u0648\u0631 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0648\u0643\u0631\u0631 \u0627\u0644\u0642\u0641\u0632\u0629\u060c \u0645\u0639 \u062a\u0628\u062f\u064a\u0644 \u0642\u062f\u0645\u064a\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062a\u0628\u062f\u064a\u0644 \u0645\u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0645\u0639 \u0643\u0644 \u0642\u0641\u0632\u0629 \u0644\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0371","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0371-S4pwGlc.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0371-S4pwGlc.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"ea2bfb95-c93f-5d85-8135-ef959c322517","source_id":"0372","name_en":"dumbbell preacher curl","name_ar":"\u062d\u0644\u064a\u0642\u0629 \u0648\u0627\u0639\u0638 \u0627\u0644\u062f\u0645\u0628\u0644","match_names":["dumbbell preacher curl"],"muscle":"biceps","equipment":"dumbbell","aliases":["dumbbell preacher curl"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Sit on a preacher curl bench with your upper arms resting on the pad and your chest against it.\nHold a dumbbell in each hand with your palms facing up and your arms fully extended.\nKeeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\nContinue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.\nHold the contracted position for a brief pause as you squeeze your biceps.\nInhale and slowly begin to lower the dumbbells back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0627\u0644\u0648\u0627\u0639\u0638 \u0627\u0644\u0645\u0644\u062a\u0641 \u0645\u0639 \u0648\u0636\u0639 \u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u062a\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0648\u0633\u0627\u062f\u0629 \u0648\u0635\u062f\u0631\u0643 \u0639\u0644\u064a\u0647.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0639\u0644\u0649 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u062a\u064a\u0646 \u062b\u0627\u0628\u062a\u062a\u064a\u0646\u060c \u0648\u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0644\u0641 \u0627\u0644\u0623\u0648\u0632\u0627\u0646 \u0623\u062b\u0646\u0627\u0621 \u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u062d\u062a\u0649 \u062a\u0646\u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646 \u0628\u0634\u0643\u0644 \u0643\u0627\u0645\u0644 \u0648\u064a\u0635\u0628\u062d \u0627\u0644\u062f\u0645\u0628\u0644 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641.\n\u0627\u062d\u062a\u0641\u0638 \u0628\u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0646\u0642\u0628\u0636\u0629 \u0644\u062a\u0648\u0642\u0641 \u0642\u0635\u064a\u0631 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u0648\u0627\u0628\u062f\u0623 \u0628\u0628\u0637\u0621 \u0641\u064a \u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0372","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0372-jivWf8n.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0372-jivWf8n.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"8d3a3089-21d6-5e6f-876e-ade1d8caf103","source_id":"1673","name_en":"dumbbell preacher curl over exercise ball","name_ar":"\u0648\u0627\u0639\u0638 \u0627\u0644\u062f\u0645\u0628\u0644 \u064a\u062a\u062c\u0639\u062f \u0641\u0648\u0642 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646","match_names":["dumbbell preacher curl over exercise ball"],"muscle":"biceps","equipment":"dumbbell","aliases":["dumbbell preacher curl over exercise ball"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Sit on an exercise ball with your feet flat on the ground and your back straight.\nHold a dumbbell in one hand with an underhand grip, resting your elbow on the exercise ball.\nKeeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.\nPause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.\nRepeat for the desired number of repetitions, then switch arms.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646 \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u064a\u062f \u0648\u0627\u062d\u062f\u0629 \u0628\u0642\u0628\u0636\u0629 \u0633\u0641\u0644\u064a\u0629\u060c \u0645\u0639 \u0648\u0636\u0639 \u0645\u0631\u0641\u0642\u0643 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u0639\u0644\u0648\u064a \u062b\u0627\u0628\u062a\u064b\u0627\u060c \u062b\u0645 \u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0644\u0641 \u0627\u0644\u062f\u0645\u0628\u0644 \u0646\u062d\u0648 \u0643\u062a\u0641\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u0648\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u0630\u0631\u0627\u0639\u064a\u0646.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1673","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1673-hwygydB.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1673-hwygydB.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"0243f584-87ef-5e0d-8591-ff6bff7d1021","source_id":"1293","name_en":"dumbbell press on exercise ball","name_ar":"\u0627\u0636\u063a\u0637 \u0628\u0627\u0644\u062f\u0645\u0628\u0644 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646","match_names":["dumbbell press on exercise ball"],"muscle":"chest","equipment":"dumbbell","aliases":["dumbbell press on exercise ball"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Sit on an exercise ball with your feet flat on the ground and dumbbells in each hand, resting on your thighs.\nSlowly walk your feet forward, rolling the exercise ball until your lower back is supported on the ball and your knees are at a 90-degree angle.\nRaise the dumbbells to shoulder height, palms facing forward.\nPress the dumbbells upward until your arms are fully extended.\nPause for a moment at the top, then slowly lower the dumbbells back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646 \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u0645\u0639 \u0627\u0644\u0627\u0633\u062a\u0631\u0627\u062d\u0629 \u0639\u0644\u0649 \u0641\u062e\u0630\u064a\u0643.\n\u0642\u0645 \u0628\u0627\u0644\u0645\u0634\u064a \u0628\u0628\u0637\u0621 \u0628\u0642\u062f\u0645\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645\u060c \u0645\u0639 \u062f\u062d\u0631\u062c\u0629 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646 \u062d\u062a\u0649 \u064a\u062a\u0645 \u062f\u0639\u0645 \u0623\u0633\u0641\u0644 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0643\u0631\u0629 \u0648\u062a\u0643\u0648\u0646 \u0631\u0643\u0628\u062a\u064a\u0643 \u0628\u0632\u0627\u0648\u064a\u0629 90 \u062f\u0631\u062c\u0629.\n\u0627\u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0625\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u062f\u0645\u0628\u0644 \u0644\u0623\u0639\u0644\u0649 \u062d\u062a\u0649 \u064a\u062a\u0645 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1293","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["shoulders","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1293-O8o7q4d.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1293-O8o7q4d.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"25cda880-7a7a-5cd3-82f3-1a220a7d0314","source_id":"0373","name_en":"dumbbell pronate-grip triceps extension","name_ar":"\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0639\u0636\u0644\u0629 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633 \u0628\u0642\u0628\u0636\u0629 \u0627\u0644\u062f\u0645\u0628\u0644","match_names":["dumbbell pronate-grip triceps extension"],"muscle":"triceps","equipment":"dumbbell","aliases":["dumbbell pronate-grip triceps extension"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Sit on a bench or chair with your back straight and feet flat on the ground.\nHold a dumbbell with both hands, palms facing down, and extend your arms straight up overhead.\nKeeping your upper arms close to your head and elbows pointing forward, slowly lower the dumbbell behind your head by bending your elbows.\nPause for a moment, then extend your arms back up to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0623\u0648 \u0643\u0631\u0633\u064a \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645 \u0648\u0642\u062f\u0645\u0627\u0643 \u0645\u0633\u0637\u062d\u062a\u0627\u0646 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0633\u0641\u0644\u060c \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0644\u0644\u0623\u0639\u0644\u0649.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u062a\u064a\u0646 \u0628\u0627\u0644\u0642\u0631\u0628 \u0645\u0646 \u0631\u0623\u0633\u0643 \u0648\u0645\u0631\u0641\u0642\u064a\u0643 \u0645\u062a\u062c\u0647\u064a\u0646 \u0644\u0644\u0623\u0645\u0627\u0645\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628\u0637\u0621 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0642\u0645 \u0628\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0373","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0373-bpJL2Qs.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0373-bpJL2Qs.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"a917ca45-4306-51e5-833e-e3d526c03eec","source_id":"0374","name_en":"dumbbell prone incline curl","name_ar":"\u062d\u0644\u064a\u0642\u0629 \u0645\u0627\u0626\u0644\u0629 \u0639\u0631\u0636\u0629 \u0644\u0644\u062f\u0645\u0628\u0644","match_names":["dumbbell prone incline curl"],"muscle":"biceps","equipment":"dumbbell","aliases":["dumbbell prone incline curl"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Adjust the bench to a 45-degree incline.\nLie face down on the bench with your chest and stomach resting against it.\nHold a dumbbell in each hand with your palms facing down and your arms fully extended.\nKeeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\nContinue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.\nHold the contracted position for a brief pause as you squeeze your biceps.\nInhale and slowly begin to lower the dumbbells back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0644\u0645\u0642\u0639\u062f \u0639\u0644\u0649 \u0645\u064a\u0644 \u0642\u062f\u0631\u0647 45 \u062f\u0631\u062c\u0629.\n\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0648\u062c\u0647\u0643 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0645\u0639 \u0648\u0636\u0639 \u0635\u062f\u0631\u0643 \u0648\u0628\u0637\u0646\u0643 \u0639\u0644\u064a\u0647.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0633\u0641\u0644 \u0648\u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u062a\u064a\u0646 \u062b\u0627\u0628\u062a\u062a\u064a\u0646\u060c \u0648\u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0644\u0641 \u0627\u0644\u0623\u0648\u0632\u0627\u0646 \u0623\u062b\u0646\u0627\u0621 \u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0631\u0641\u0639 \u0627\u0644\u0623\u0648\u0632\u0627\u0646 \u062d\u062a\u0649 \u062a\u0646\u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646 \u0628\u0634\u0643\u0644 \u0643\u0627\u0645\u0644 \u0648\u064a\u0635\u0628\u062d \u0627\u0644\u062f\u0645\u0628\u0644 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641.\n\u0627\u062d\u062a\u0641\u0638 \u0628\u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0646\u0642\u0628\u0636\u0629 \u0644\u062a\u0648\u0642\u0641 \u0642\u0635\u064a\u0631 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u0648\u0627\u0628\u062f\u0623 \u0628\u0628\u0637\u0621 \u0641\u064a \u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0374","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0374-mwpPcr1.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0374-mwpPcr1.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"44656274-0dcd-5ce2-887c-3c2cd6017aaa","source_id":"1674","name_en":"dumbbell prone incline hammer curl","name_ar":"\u062d\u0644\u064a\u0642\u0629 \u0627\u0644\u0645\u0637\u0631\u0642\u0629 \u0627\u0644\u0645\u0646\u062d\u062f\u0631\u0629 \u0627\u0644\u0645\u0639\u0631\u0636\u0629 \u0644\u0644\u062f\u0645\u0628\u0644","match_names":["dumbbell prone incline hammer curl"],"muscle":"biceps","equipment":"dumbbell","aliases":["dumbbell prone incline hammer curl"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Adjust the bench to a 45-degree incline.\nLie face down on the bench with a dumbbell in each hand, palms facing each other.\nAllow your arms to hang straight down towards the floor, keeping your elbows slightly bent.\nKeeping your upper arms stationary, exhale and curl the weights while contracting your biceps.\nContinue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.\nHold the contracted position for a brief pause as you squeeze your biceps.\nInhale and slowly begin to lower the dumbbells back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0644\u0645\u0642\u0639\u062f \u0639\u0644\u0649 \u0645\u064a\u0644 \u0642\u062f\u0631\u0647 45 \u062f\u0631\u062c\u0629.\n\u0627\u0633\u062a\u0644\u0642\u0650 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0648\u0648\u062c\u0647\u0643 \u0644\u0644\u0623\u0633\u0641\u0644 \u0645\u0639 \u0648\u062c\u0648\u062f \u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u0645\u0639 \u0648\u0636\u0639 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636.\n\u0627\u0633\u0645\u062d \u0644\u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u062a\u062f\u0644\u064a \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u062a\u064a\u0646 \u062b\u0627\u0628\u062a\u062a\u064a\u0646\u060c \u0648\u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0644\u0641 \u0627\u0644\u0623\u0648\u0632\u0627\u0646 \u0623\u062b\u0646\u0627\u0621 \u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u062d\u062a\u0649 \u062a\u0646\u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646 \u0628\u0634\u0643\u0644 \u0643\u0627\u0645\u0644 \u0648\u064a\u0635\u0628\u062d \u0627\u0644\u062f\u0645\u0628\u0644 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641.\n\u0627\u062d\u062a\u0641\u0638 \u0628\u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0646\u0642\u0628\u0636\u0629 \u0644\u062a\u0648\u0642\u0641 \u0642\u0635\u064a\u0631 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u0648\u0627\u0628\u062f\u0623 \u0628\u0628\u0637\u0621 \u0641\u064a \u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1674","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1674-cWemPG8.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1674-cWemPG8.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"f73219ca-a064-5470-8ab1-ab1d47669c56","source_id":"0375","name_en":"dumbbell pullover","name_ar":"\u0627\u0644\u0633\u062a\u0631\u0629 \u0627\u0644\u062f\u0645\u0628\u0644","match_names":["dumbbell pullover"],"muscle":"chest","equipment":"dumbbell","aliases":["dumbbell pullover"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Lie flat on a bench with your head at one end and your feet on the floor.\nHold a dumbbell with both hands and extend your arms straight above your chest.\nKeeping a slight bend in your elbows, slowly lower the dumbbell behind your head until you feel a stretch in your chest and shoulders.\nPause for a moment, then raise the dumbbell back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0639 \u0648\u0636\u0639 \u0631\u0623\u0633\u0643 \u0641\u064a \u0623\u062d\u062f \u0637\u0631\u0641\u064a\u0647 \u0648\u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0641\u0648\u0642 \u0635\u062f\u0631\u0643.\n\u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0646\u062d\u0646\u0627\u0621 \u0637\u0641\u064a\u0641 \u0641\u064a \u0645\u0631\u0641\u0642\u064a\u0643\u060c \u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628\u0637\u0621 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643 \u062d\u062a\u0649 \u062a\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0635\u062f\u0631\u0643 \u0648\u0643\u062a\u0641\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0375","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["latissimus dorsi","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0375-9XjtHvS.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0375-9XjtHvS.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"97cc77d3-bd74-58eb-8321-d69a4caf9107","source_id":"1294","name_en":"dumbbell pullover hip extension on exercise ball","name_ar":"\u0628\u0644\u0648\u0641\u0631 \u0627\u0644\u062f\u0645\u0628\u0644\u060c \u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0648\u0631\u0643 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646","match_names":["dumbbell pullover hip extension on exercise ball"],"muscle":"chest","equipment":"dumbbell","aliases":["dumbbell pullover hip extension on exercise ball"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Sit on an exercise ball with your feet flat on the ground and the dumbbell resting on your thighs.\nSlowly walk your feet forward, rolling the exercise ball down your back until your head, neck, and upper back are supported on the ball.\nHold the dumbbell with both hands and extend your arms straight up over your chest, keeping a slight bend in your elbows.\nLower the dumbbell behind your head, keeping your arms straight and maintaining control.\nPause for a moment, then raise the dumbbell back to the starting position.\nWhile keeping your arms extended, lift your hips off the ground, squeezing your glutes and engaging your core.\nLower your hips back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646 \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0627\u0644\u062f\u0645\u0628\u0644 \u0639\u0644\u0649 \u0641\u062e\u0630\u064a\u0643.\n\u0642\u0645 \u0628\u0627\u0644\u0645\u0634\u064a \u0628\u0628\u0637\u0621 \u0628\u0642\u062f\u0645\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645\u060c \u0645\u0639 \u062f\u062d\u0631\u062c\u0629 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646 \u0625\u0644\u0649 \u0623\u0633\u0641\u0644 \u0638\u0647\u0631\u0643 \u062d\u062a\u0649 \u064a\u062a\u0645 \u062f\u0639\u0645 \u0631\u0623\u0633\u0643 \u0648\u0631\u0642\u0628\u062a\u0643 \u0648\u0623\u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0643\u0631\u0629.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0641\u0648\u0642 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0646\u062d\u0646\u0627\u0621 \u0637\u0641\u064a\u0641 \u0641\u064a \u0645\u0631\u0641\u0642\u064a\u0643.\n\u0627\u062e\u0641\u0636 \u0627\u0644\u062f\u0645\u0628\u0644 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646 \u0648\u062a\u062d\u0643\u0645\u0643.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0645\u062a\u062f\u062a\u064a\u0646\u060c \u0627\u0631\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629 \u0648\u0627\u0634\u063a\u0644 \u062c\u0630\u0639\u0643.\n\u062e\u0641\u0636 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1294","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["triceps","shoulders","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1294-lI7easp.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1294-lI7easp.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"b0790b82-8bdb-56ce-89fd-c83ae138e3f9","source_id":"1295","name_en":"dumbbell pullover on exercise ball","name_ar":"\u0633\u062a\u0631\u0629 \u0627\u0644\u062f\u0645\u0628\u0644 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646","match_names":["dumbbell pullover on exercise ball"],"muscle":"chest","equipment":"dumbbell","aliases":["dumbbell pullover on exercise ball"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Sit on an exercise ball and hold a dumbbell with both hands above your chest, arms extended.\nSlowly lower the dumbbell behind your head while keeping your arms straight.\nPause for a moment, then raise the dumbbell back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0629 \u062a\u0645\u0631\u064a\u0646 \u0648\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643 \u0641\u0648\u0642 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643.\n\u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628\u0637\u0621 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643 \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1295","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["triceps","latissimus dorsi"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1295-FSD6PGL.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1295-FSD6PGL.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"47009403-8300-5c5f-8bdc-124f7db48e0f","source_id":"1700","name_en":"dumbbell push press","name_ar":"\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u062f\u0645\u0628\u0644","match_names":["dumbbell push press"],"muscle":"shoulders","equipment":"dumbbell","aliases":["dumbbell push press"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level.\nBend your knees slightly and dip your body down, then explosively extend your legs and press the dumbbells overhead.\nLock out your arms at the top of the movement, then lower the dumbbells back to shoulder level.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0627\u062d\u0645\u0644 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u064b\u0627 \u0648\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0644\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0645\u062f \u0633\u0627\u0642\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u062a\u0641\u062c\u0631 \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0641\u0648\u0642 \u0631\u0623\u0633\u0643.\n\u0627\u0642\u0641\u0644 \u0630\u0631\u0627\u0639\u064a\u0643 \u0641\u064a \u0623\u0639\u0644\u0649 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644\u0632 \u0625\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1700","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["triceps","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1700-FS63wTN.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1700-FS63wTN.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"37f463e6-5c95-5fec-8dca-a2bec1442705","source_id":"0376","name_en":"dumbbell raise","name_ar":"\u0631\u0641\u0639 \u0627\u0644\u062f\u0645\u0628\u0644","match_names":["dumbbell raise"],"muscle":"shoulders","equipment":"dumbbell","aliases":["dumbbell raise"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.\nKeep your back straight and engage your core.\nRaise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows.\nPause for a moment at the top, then slowly lower your arms back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0646\u062d\u0648 \u062c\u0633\u0645\u0643.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0627\u0634\u063a\u0644 \u0642\u0644\u0628\u0643.\n\u0627\u0631\u0641\u0639\u064a \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d\u0627 \u0645\u0648\u0627\u0632\u064a\u064a\u0646 \u0644\u0644\u0623\u0631\u0636\u064a\u0629\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0646\u062d\u0646\u0627\u0621 \u0628\u0633\u064a\u0637 \u0641\u064a \u0645\u0631\u0641\u0642\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u064